import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CPHNBVkq.js";const r="/corbi/screenshots/chat.png",m=JSON.parse('{"title":"Chat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat.md","filePath":"guide/chat.md"}'),s={name:"guide/chat.md"};function n(l,e,c,h,u,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h1><p>Chat is a conversation with Corbi. Ask a question, describe what you&#39;re trying to do, and Corbi responds — sometimes with a short form for you to fill in so it can help more precisely.</p><p><img src="'+r+'" alt="A conversation with Corbi"></p><h2 id="starting-a-conversation" tabindex="-1">Starting a conversation <a class="header-anchor" href="#starting-a-conversation" aria-label="Permalink to &quot;Starting a conversation&quot;">​</a></h2><ol><li>Select <strong>Chat</strong> in the navigation drawer.</li><li>Type your message in the input at the bottom of the screen and send it.</li></ol><p>Corbi creates a new conversation from your first message and replies. Your message appears right away; while Corbi is working on a reply you&#39;ll see a brief pending indicator.</p><h2 id="continuing-a-conversation" tabindex="-1">Continuing a conversation <a class="header-anchor" href="#continuing-a-conversation" aria-label="Permalink to &quot;Continuing a conversation&quot;">​</a></h2><p>Keep typing in the same conversation to follow up — Corbi keeps the context of what you&#39;ve already discussed. The view scrolls to the newest message automatically as the conversation grows.</p><h2 id="chat-forms" tabindex="-1">Chat forms <a class="header-anchor" href="#chat-forms" aria-label="Permalink to &quot;Chat forms&quot;">​</a></h2><p>Some replies include a <strong>chat form</strong> — a short interactive form that collects specific details Corbi needs. When a reply has one, you&#39;ll see it in the conversation.</p><ul><li>Select the form to open it.</li><li>Fill in the fields and submit.</li><li>Corbi uses your answers to continue helping.</li></ul><p>If a conversation opens with a form ready for you, it may pop up automatically so you can respond right away.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Chat forms are there to save you from typing everything out. When one appears, filling it in is usually the fastest way to get what you asked for.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Be specific. &quot;Show me overdue invoices for Acme&quot; gets a better result than &quot;invoices.&quot;</li><li>If Corbi asks a clarifying question or shows a form, answering it helps it give you a precise response.</li><li>Need Corbi to <em>do</em> something on a recurring or structured basis rather than just answer? That&#39;s what <a href="./tasks.html">Tasks</a> are for.</li></ul>',15)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
